export function ledger(viewport='desktop'){
 const rows=[];let time=0;const add=(method,args=[],name)=>{const startedAt=time;time+=method==='waitForTimeout'?args[0]:1;rows.push({id:rows.length+1,path:method==='move'||method==='down'||method==='up'?`page.mouse.${method}`:name?`page.getByRole(["button",{"name":"${name}","exact":true}]).${method}`:`page.${method}`,args,startedAt,endedAt:time,outcome:'completed'});};
 const wait=ms=>add('waitForTimeout',[ms]);const drag=d=>{const p={x:200,y:120};add('move',[p.x,p.y]);add('down');for(let i=1;i<=12;i++){add('move',[p.x+d*i*4,p.y+Math.sin(i/3)*8]);wait(75);}add('up');};
 wait(1500);drag(1);drag(-1);drag(1);add('click',[],'Rotate');for(let i=0;i<6;i++){add('click',[],'Lights');wait(350);}add('click',[],'Rotate');wait(4000);add('click',[{timeout:15000}],'Camera');add('click',[{timeout:15000}],'Cabin preview · work in progress');drag(1);drag(-1);add('focus');for(let i=0;i<8;i++){add('press',[i<4?'ArrowLeft':'ArrowRight']);wait(100);}for(const seat of ['Passenger','Rear seat','Driver']){add('click',[],seat);wait(350);}wait(4000);add('setViewportSize',[viewport==='mobile'?{width:430,height:900}:{width:1280,height:800}]);wait(1000);drag(1);wait(4000);return rows;
}
